// 1. Get the form answers and the AI review
const form = $('On form submission').first().json;
const r = $input.first().json.output;

const name = (form['Full Name'] || 'there').split(' ')[0];   // first name only
const role = form['Target Role'];
const score = Math.min(100, Math.max(0, Number(r.overall_score) || 0));

// 2. Pick a color and label based on the score
const color = score >= 75 ? '#188038' : score >= 60 ? '#e8710a' : '#d93025';
const label = score >= 90 ? 'Interview-ready' : score >= 75 ? 'Strong' : score >= 60 ? 'Needs work' : 'Major gaps';

// 3. Escape text so user input or AI output can't break the HTML
const esc = (s) => String(s ?? '')
  .replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;');

// 4. Small helpers for repeated pieces
const list = (items) => (items || [])
  .map((i) => `<li style="margin-bottom:6px">${esc(i)}</li>`).join('');

const section = (title) => `<h3 style="margin:24px 0 10px;font-size:17px">${title}</h3>`;

const improvements = (r.improvements || []).map((imp, i) => `
  <div style="border-left:4px solid #e8710a;background:#fff8f0;padding:10px 14px;margin-bottom:10px;border-radius:6px">
    <b>${i + 1}. ${esc(imp.issue)}</b><br>
    <span style="color:#3c4043">✅ Fix: ${esc(imp.fix)}</span>
  </div>`).join('');

const keywords = (r.missing_keywords || []).map((k) =>
  `<span style="display:inline-block;background:#e8f0fe;color:#1967d2;padding:4px 10px;border-radius:12px;margin:3px;font-size:13px">${esc(k)}</span>`
).join('');

// 5. Put the email together
const html = `
<div style="font-family:Arial,sans-serif;max-width:600px;margin:auto;color:#202124">
  <h2 style="margin-bottom:4px">📄 Your AI Resume Review</h2>
  <p style="color:#5f6368;margin-top:0">Hi ${esc(name)}, here's your review for the role of <b>${esc(role)}</b>.</p>

  <div style="text-align:center;border:1px solid #e0e0e0;border-radius:10px;padding:20px;margin:16px 0">
    <div style="font-size:48px;font-weight:bold;color:${color}">${score}<span style="font-size:20px;color:#9aa0a6">/100</span></div>
    <div style="display:inline-block;background:${color};color:#fff;padding:3px 12px;border-radius:12px;font-size:13px">${label}</div>
    <div style="background:#f1f3f4;border-radius:6px;height:10px;margin:14px 0 10px">
      <div style="background:${color};width:${score}%;height:10px;border-radius:6px"></div>
    </div>
    <p style="margin:0;font-style:italic">"${esc(r.verdict)}"</p>
  </div>

  ${section('💪 Strengths')}
  <ul style="padding-left:20px">${list(r.strengths)}</ul>

  ${section('🛠️ Top improvements')}
  ${improvements}

  ${section('🔑 Missing keywords')}
  <div>${keywords}</div>

  ${section('🤖 ATS tips')}
  <ul style="padding-left:20px">${list(r.ats_tips)}</ul>

  ${section('✍️ Suggested professional summary')}
  <div style="background:#f8f9fa;border:1px dashed #bdc1c6;padding:14px;border-radius:8px">${esc(r.rewritten_summary)}</div>

  <p style="color:#9aa0a6;font-size:12px;text-align:center;margin-top:28px">
    AI-generated feedback · Always review suggestions before using them
  </p>
</div>`;

return [{
  json: {
    to: form['Email'],
    subject: `📄 Your resume review: ${score}/100 for ${role}`,
    html,
  },
}];
